using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using DuckGame.Maps.V08;
namespace DuckGame.Maps.V09 {
[InitializeOnLoad] public static class PolishBuilder {
 const string R="Assets/DuckGame/Maps/V09/",D="docs/verification/v09/";
 static PolishBuilder(){EditorApplication.update+=Tick;}
 static void Tick(){string q=D+"build-request.txt";if(EditorApplication.isPlaying||EditorApplication.isCompiling||!File.Exists(q))return;var c=File.ReadAllText(q).Trim();if(c.Length==0)return;File.WriteAllText(q,"");try{if(c=="build")Build();else if(c=="band-outline"){SetHatOutline(UnityEngine.Object.FindObjectOfType<OrbShooter>().hat);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());}else if(c=="materials"){ApplySkins(UnityEngine.Object.FindObjectOfType<OrbShooter>());var b=AssetDatabase.LoadAssetAtPath<Material>(R+"Generated/Tailored hat band.mat");b.SetVector("_Tint",new Vector4(.33f,.35f,.34f,1));EditorUtility.SetDirty(b);var e=AssetDatabase.LoadAssetAtPath<Material>(R+"Generated/Silver cloth seam.mat");e.SetVector("_Tint",new Vector4(.62f,.63f,.60f,1));EditorUtility.SetDirty(e);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());}else if(c=="refine"){var m=AssetDatabase.LoadAssetAtPath<Mesh>(R+"Generated/TailoredHat.asset");var vs=m.vertices;for(int i=vs.Length-388;i<vs.Length;i++){var d=new Vector3(vs[i].x,vs[i].y+.22f,0).normalized;vs[i]+=d*.003f;}m.vertices=vs;m.RecalculateBounds();EditorUtility.SetDirty(m);foreach(var p in Directory.GetFiles(R+"Generated","*_Outline.mat")){var mat=AssetDatabase.LoadAssetAtPath<Material>(p);mat.SetFloat("_WidthPixels",p.Contains("Eye")?.65f:.9f);EditorUtility.SetDirty(mat);}AssetDatabase.SaveAssets();}else if(c=="fixband"){var m=AssetDatabase.LoadAssetAtPath<Mesh>(R+"Generated/TailoredHat.asset");for(int s=m.subMeshCount-2;s<m.subMeshCount;s++){var ts=m.GetTriangles(s);for(int i=0;i<ts.Length;i+=3){int a=ts[i+1];ts[i+1]=ts[i+2];ts[i+2]=a;}m.SetTriangles(ts,s);}EditorUtility.SetDirty(m);AssetDatabase.SaveAssets();}}catch(Exception e){File.WriteAllText(D+"build-error.txt",e.ToString());Debug.LogException(e);}}
 static Material Save(Material m,string name){name=string.Concat(name.Select(ch=>Path.GetInvalidFileNameChars().Contains(ch)?'_':ch));m.name=name;var path=R+"Generated/"+name+".mat";var old=AssetDatabase.LoadAssetAtPath<Material>(path);if(old!=null){EditorUtility.CopySerialized(m,old);UnityEngine.Object.DestroyImmediate(m);EditorUtility.SetDirty(old);return old;}AssetDatabase.CreateAsset(m,path);return m;}
 static void Build(){string dest=R+"Generated/PolishedGrove.unity";if(File.Exists(dest))throw new Exception("V09 already exists; refusing overwrite");var old=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(old.isDirty&&!EditorSceneManager.SaveScene(old,D+"baseline/UnsavedScene.unity",true))throw new Exception("Safety save failed");if(!AssetDatabase.CopyAsset("Assets/DuckGame/Maps/V08/Generated/MerchantGrove.unity",dest))throw new Exception("Scene copy failed");var scene=EditorSceneManager.OpenScene(dest);var shooter=UnityEngine.Object.FindObjectOfType<OrbShooter>();var hat=shooter.hat;ApplySkins(shooter);
 var band=new Material(Shader.Find("Duck Game/V09/Tailored Toon"));var col=new Color(.33f,.35f,.34f);band.SetVector("_Tint",col);band.SetFloat("_Sheen",.012f);band=Save(band,"Tailored hat band");var seam=new Material(band);seam.SetVector("_Tint",new Color(.62f,.63f,.60f));seam=Save(seam,"Silver cloth seam");AddBand(hat,band,seam);
 shooter.orbMaterial=Save(new Material(Shader.Find("Duck Game/V09/Orb Pearl")),"Pearl orb");shooter.trailMaterial=Save(new Material(Shader.Find("Duck Game/V09/Orb Trail")),"Soft orb trail");shooter.GetComponent<CombatFeedback>().polished=true;foreach(var t in UnityEngine.Object.FindObjectsOfType<TargetDummy>())t.directional=true;
 var audio=UnityEngine.Object.FindObjectOfType<FeedbackAudio>();audio.polished=true;audio.clips=new[]{"Shot","Ready","Environment","Target","Purchase","Denied"}.Select(n=>AssetDatabase.LoadAssetAtPath<AudioClip>(R+"Audio/"+n+".wav")).ToArray();audio.wood=AssetDatabase.LoadAssetAtPath<AudioClip>(R+"Audio/Wood.wav");
 if(audio.clips.Any(c=>c==null))throw new Exception("Missing audio");if(!EditorSceneManager.SaveScene(scene,dest))throw new Exception("V09 save failed");AssetDatabase.SaveAssets();File.WriteAllText(D+"build.txt","V09 saved; preserved FBX, rig, source materials and centerline; 582 appended weighted band/seam vertices.");Debug.Log("V09_BUILD_OK");}
 static void ApplySkins(OrbShooter shooter){var hm=shooter.hat.hat.sharedMaterials;if(hm.Length>=3){hm[hm.Length-2]=AssetDatabase.LoadAssetAtPath<Material>(R+"Generated/Tailored hat band.mat");hm[hm.Length-1]=AssetDatabase.LoadAssetAtPath<Material>(R+"Generated/Silver cloth seam.mat");shooter.hat.hat.sharedMaterials=hm;}var cache=new Dictionary<Material,Material>();foreach(var skin in UnityEngine.Object.FindObjectOfType<MerchantTrade>().motor.GetComponentsInChildren<SkinnedMeshRenderer>()){if(skin.name.EndsWith("_Outline")){var m=new Material(skin.sharedMaterial);m.SetFloat("_WidthPixels",skin.name.StartsWith("Eye")?.65f:.9f);skin.sharedMaterials=Enumerable.Repeat(Save(m,skin.name),skin.sharedMesh.subMeshCount).ToArray();continue;}var ms=skin.sharedMaterials;for(int j=0;j<ms.Length;j++){var src=ms[j];if(src==null)throw new Exception("Missing material on "+skin.name);if(AssetDatabase.GetAssetPath(src).StartsWith(R)){ms[j]=src;continue;}if(!cache.TryGetValue(src,out var m)){m=new Material(Shader.Find("Duck Game/V09/Tailored Toon"));m.SetVector("_Tint",src.GetVector("_Tint"));m.SetFloat("_Sheen",src.name.Contains("Blue")?.075f:src.name.Contains("Orange")?.035f:src.name.Contains("Ink")?.025f:.008f);cache[src]=Save(m,Path.GetFileNameWithoutExtension(AssetDatabase.GetAssetPath(src)));}ms[j]=m;}skin.sharedMaterials=ms;}SetHatOutline(shooter.hat);File.WriteAllText(D+"material-audit.txt","skins="+UnityEngine.Object.FindObjectOfType<MerchantTrade>().motor.GetComponentsInChildren<SkinnedMeshRenderer>().Length+"; cloned base materials="+cache.Count);}
 static void SetHatOutline(HatBulge h){if(h.hat.sharedMesh.subMeshCount<3)return;var hidden=Save(new Material(Shader.Find("Duck Game/V09/Omit Band Outline")),"No band outline");var ms=h.outline.sharedMaterials;ms[ms.Length-2]=ms[ms.Length-1]=hidden;h.outline.sharedMaterials=ms;}
 static void AddBand(HatBulge h,Material band,Material seam){var src=h.hat.sharedMesh;var m=UnityEngine.Object.Instantiate(src);m.name="Tailored hat with integrated band";var originalVertices=src.vertices;var originalWeights=src.boneWeights;var vs=originalVertices.ToList();var ns=src.normals.ToList();var ws=src.boneWeights.ToList();var uv=src.uv.ToList();while(uv.Count<vs.Count)uv.Add(Vector2.zero);var triangles=new List<int>();var edges=new List<int>();int count=96;
 for(int strip=0;strip<3;strip++){int start=vs.Count;float low=strip==0?2.548f:strip==1?2.548f:2.597f,high=strip==0?2.605f:low+.005f;for(int row=0;row<2;row++){float z=row==0?low:high;float rx=Mathf.Lerp(.337f,.313f,(z-2.55f)/.06f)+(strip==0?.006f:.009f),ry=rx*.915f;for(int i=0;i<=count;i++){float a=i*Mathf.PI*2/count;Vector3 p=new Vector3(Mathf.Cos(a)*rx,-.22f+Mathf.Sin(a)*ry,z);int nearest=0;float best=float.MaxValue;for(int v=0;v<src.vertexCount;v++){float d=(originalVertices[v]-p).sqrMagnitude;if(d<best){best=d;nearest=v;}}vs.Add(p);ns.Add(new Vector3(Mathf.Cos(a),Mathf.Sin(a),.27f).normalized);ws.Add(originalWeights[nearest]);uv.Add(new Vector2(i/(float)count,row));}}for(int i=0;i<count;i++){int a=start+i,b=a+count+1;var list=strip==0?triangles:edges;list.AddRange(new[]{a,a+1,b,a+1,b+1,b});}}
 m.vertices=vs.ToArray();m.normals=ns.ToArray();m.boneWeights=ws.ToArray();m.uv=uv.ToArray();m.subMeshCount=src.subMeshCount+2;for(int s=0;s<src.subMeshCount;s++)m.SetTriangles(src.GetTriangles(s),s);m.SetTriangles(triangles,src.subMeshCount);m.SetTriangles(edges,src.subMeshCount+1);m.RecalculateBounds();AssetDatabase.CreateAsset(m,R+"Generated/TailoredHat.asset");h.hat.sharedMesh=m;h.hat.sharedMaterials=h.hat.sharedMaterials.Concat(new[]{band,seam}).ToArray();h.outline.sharedMesh=m;h.outline.sharedMaterials=Enumerable.Repeat(h.outline.sharedMaterial,m.subMeshCount).ToArray();SetHatOutline(h);}
}
}
